class Cache:
    def __init__(self, state):
        self.state = state              # plain attribute: a reference

    def swap_state(self, other):
        self.state, other.state = other.state, self.state   # RHS first: cannot fail

    def commit(self, fresh):
        self.state = fresh              # rollback assigns the old reference back

